previewCss:
.darma-loader-darma-b12-popcorn-pop { --accent: var(--loader-color, #ef4444); --accent-2: var(--loader-secondary-color, #fbbf24); width: var(--loader-size, 100px); height: var(--loader-size, 100px); position: relative; }
.darma-loader-darma-b12-popcorn-pop .darma-loader-darma-b12-popcorn-pop__tub { position: absolute; bottom: 2%; left: 19%; width: 62%; height: 44%; clip-path: polygon(5% 0%, 95% 0%, 84% 100%, 16% 100%); background: repeating-linear-gradient(90deg, var(--accent) 0 16%, #f8fafc 16% 32%); }
.darma-loader-darma-b12-popcorn-pop span { position: absolute; bottom: 42%; width: 15%; height: 15%; border-radius: 44% 56% 48% 52% / 52% 46% 54% 48%; background: radial-gradient(circle at 38% 34%, #fff, color-mix(in srgb, #fff 52%, var(--accent-2))); animation: darma-loader-darma-b12-popcorn-pop-pop calc(var(--loader-speed, 1s) * 1.9) ease-out infinite; }
.darma-loader-darma-b12-popcorn-pop span:nth-child(1) { left: 22%; --drift: -58%; animation-delay: 0s; }
.darma-loader-darma-b12-popcorn-pop span:nth-child(2) { left: 37%; --drift: -18%; animation-delay: calc(var(--loader-speed, 1s) * .4); }
.darma-loader-darma-b12-popcorn-pop span:nth-child(3) { left: 51%; --drift: 20%; animation-delay: calc(var(--loader-speed, 1s) * .8); }
.darma-loader-darma-b12-popcorn-pop span:nth-child(4) { left: 64%; --drift: 60%; animation-delay: calc(var(--loader-speed, 1s) * 1.2); }
@keyframes darma-loader-darma-b12-popcorn-pop-pop { 0% { opacity: 0; transform: translate(0, 20%) scale(.35) rotate(0deg); } 18% { opacity: 1; } 52% { transform: translate(var(--drift), -132%) scale(1) rotate(170deg); } 100% { opacity: 0; transform: translate(calc(var(--drift) * 1.5), 34%) scale(1) rotate(320deg); } }

